53	    public PostgresSqlCommandInfo BuildCreateTableCommand(string schema, string tableName, VectorStoreRecordModel model, bool ifNotExists = true)
54	    {
55	        if (string.IsNullOrWhiteSpace(tableName))
56	        {
57	            throw new ArgumentException("Table name cannot be null or whitespace", nameof(tableName));
58	        }
59	
60	        var keyName = model.KeyProperty.StorageName;
61	
62	        StringBuilder createTableCommand = new();
63	        createTableCommand.AppendLine($"CREATE TABLE {(ifNotExists ? "IF NOT EXISTS " : "")}{schema}.\"{tableName}\" (");
64	
65	        // Add the key column
66	        var keyPgTypeInfo = PostgresVectorStoreRecordPropertyMapping.GetPostgresTypeName(model.KeyProperty.Type);
67	        createTableCommand.AppendLine($"    \"{keyName}\" {keyPgTypeInfo.PgType} {(keyPgTypeInfo.IsNullable ? "" : "NOT NULL")},");
68	
69	        // Add the data columns
70	        foreach (var dataProperty in model.DataProperties)
71	        {
72	            string columnName = dataProperty.StorageName;
73	            var dataPgTypeInfo = PostgresVectorStoreRecordPropertyMapping.GetPostgresTypeName(dataProperty.Type);
74	            createTableCommand.AppendLine($"    \"{columnName}\" {dataPgTypeInfo.PgType} {(dataPgTypeInfo.IsNullable ? "" : "NOT NULL")},");
75	        }
76	
77	        // Add the vector columns
78	        foreach (var vectorProperty in model.VectorProperties)
79	        {
80	            string columnName = vectorProperty.StorageName;
81	            var vectorPgTypeInfo = PostgresVectorStoreRecordPropertyMapping.GetPgVectorTypeName(vectorProperty);
82	            createTableCommand.AppendLine($"    \"{columnName}\" {vectorPgTypeInfo.PgType} {(vectorPgTypeInfo.IsNullable ? "" : "NOT NULL")},");
83	        }
84	
85	        createTableCommand.AppendLine($"    PRIMARY KEY (\"{keyName}\")");
86	
87	        createTableCommand.AppendLine(");");
88	
89	        return new PostgresSqlCommandInfo(commandText: createTableCommand.ToString());
90	    }
