94	    {
95	        var indexName = $"{tableName}_{columnName}_index";
96	
97	        if (!isVector)
98	        {
99	            return new PostgresSqlCommandInfo(commandText:
100	                $@"CREATE INDEX {(ifNotExists ? "IF NOT EXISTS " : "")}""{indexName}"" ON {schema}.""{tableName}"" (""{columnName}"");"
101	            );
102	        }
103	
104	        // Only support creating HNSW index creation through the connector.
105	        var indexTypeName = indexKind switch
106	        {
107	            IndexKind.Hnsw => "hnsw",
108	            _ => throw new NotSupportedException($"Index kind '{indexKind}' is not supported for table creation. If you need to create an index of this type, please do so manually. Only HNSW indexes are supported through the vector store.")
109	        };
110	
111	        distanceFunction ??= PostgresConstants.DefaultDistanceFunction;  // Default to Cosine distance
112	
113	        var indexOps = distanceFunction switch
114	        {
115	            DistanceFunction.CosineDistance => "vector_cosine_ops",
116	            DistanceFunction.CosineSimilarity => "vector_cosine_ops",
117	            DistanceFunction.DotProductSimilarity => "vector_ip_ops",
118	            DistanceFunction.EuclideanDistance => "vector_l2_ops",
119	            DistanceFunction.ManhattanDistance => "vector_l1_ops",
120	            _ => throw new NotSupportedException($"Distance function {distanceFunction} is not supported.")
121	        };
122	
123	        return new PostgresSqlCommandInfo(
124	            commandText: $@"
125	                CREATE INDEX {(ifNotExists ? "IF NOT EXISTS " : "")} ""{indexName}"" ON {schema}.""{tableName}"" USING {indexTypeName} (""{columnName}"" {indexOps});"
126	        );
127	    }
