[SuppressMessage("Security", "CA2100:Review SQL queries for security vulnerabilities", Justification = "We need to build the full table name using schema and collection, it does not support parameterized passing.")]
internal static class PostgresSqlBuilder
{
    /// <summary>
    /// Builds a SQL command to check if a table exists in the Postgres vector store.
    /// </summary>
    /// <param name="schema">The schema of the table.</param>
    /// <param name="tableName">The name of the table.</param>
    /// <returns>The built SQL command.</returns>
    /// <remarks>
    /// The command must return a single row with a single column named "table_name" if the table exists.
    /// </remarks>
    public static NpgsqlCommand BuildDoesTableExistCommand(string schema, string tableName)
    {
        var command = new NpgsqlCommand();
        command.CommandText = """
SELECT table_name
FROM information_schema.tables
WHERE table_schema = $1
    AND table_type = 'BASE TABLE'
    AND table_name = $2
""";
        command.Parameters.Add(new NpgsqlParameter() { Value = schema });
        command.Parameters.Add(new NpgsqlParameter() { Value = tableName });
        return command;
    }

    /// <summary>
    /// Builds a SQL command to fetch all tables in the Postgres vector store.
    /// </summary>
    /// <param name="schema">The schema of the tables.</param>
    public static NpgsqlCommand BuildGetTablesCommand(string schema)
    {
        var command = new NpgsqlCommand();
        command.CommandText = """
SELECT table_name
FROM information_schema.tables
WHERE table_schema = $1 AND table_type = 'BASE TABLE'
""";
        command.Parameters.Add(new NpgsqlParameter() { Value = schema });
        return command;
    }

    /// <summary>
